package com.regsco.compras;
import android.app.*;
import android.os.Bundle;
import android.widget.*;
import android.view.*;
import android.webkit.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.net.*;
import java.io.*;
import java.util.*;
import java.math.*;
import java.text.*;
import java.util.concurrent.*;
import org.json.*;
/** Anonymous live storefront queries. Photos and the local shopping history never leave the device. */
public class OnlinePricesActivity extends Activity {
 int theme,token;boolean pharmacy;LinearLayout root,results;EditText query;Spinner shops;TextView status;
 List<JSONObject> markets=new ArrayList<>();ExecutorService worker=Executors.newSingleThreadExecutor();
 static class Offer {String name,source,url,category,image="";long price,reference;boolean conditional;}
 @Override public void onCreate(Bundle state){super.onCreate(state);theme=getIntent().getIntExtra("theme",0);pharmacy=getIntent().getBooleanExtra("pharmacy",false);
  root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackground(new ThemeSkin.Backdrop(theme));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(20,i.getSystemWindowInsetTop()+12,20,i.getSystemWindowInsetBottom()+12);return i;});setContentView(root);
  text(root,pharmacy?"Promoções online de farmácia":"Outras opções • Mix Mateus",22);
  text(root,pharmacy?"Consulte apresentação e dosagem. Entrega em Timon e frete dependem do CEP informado à farmácia.":"Somente o texto da busca é enviado. Confira a loja. O preço online pode ser diferente do preço na prateleira.",13);
  query=new EditText(this);query.setTextColor(ThemeSkin.text(theme));query.setHintTextColor(ThemeSkin.secondary(theme));query.setHint("Nome do produto e sabor (sem marca)");query.setText(getIntent().getStringExtra("query"));root.addView(query);
  shops=new Spinner(this);root.addView(shops);status=text(root,"",13);button(root,pharmacy?"Consultar":"Buscar outras opções",()->search());
  ScrollView scroll=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);scroll.addView(results);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));button(root,"Voltar ao RegsCo",()->finish());
  if(pharmacy){spinner(Arrays.asList("Pague Menos","Drogaria Globo"));button(root,"Ofertas Drogasil (site dentro do app)",()->web("https://www.drogasil.com.br/campanhas/destaques/ofertas-imperdiveis"));search();}else loadStores();
 }
 TextView text(LinearLayout parent,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(ThemeSkin.text(theme));t.setTextSize(size);t.setPadding(16,12,16,12);parent.addView(t);return t;}
 void button(LinearLayout parent,String title,Runnable action){TextView t=text(parent,title,16);t.setBackground(ThemeSkin.card(theme,20));t.setMinHeight((int)(48*getResources().getDisplayMetrics().density));t.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,8,0,8);t.setLayoutParams(lp);t.setFocusable(true);t.setOnClickListener(v->action.run());}
 void spinner(List<String> names){ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names){@Override public View getView(int i,View v,ViewGroup parent){TextView t=(TextView)super.getView(i,v,parent);t.setTextColor(ThemeSkin.text(theme));return t;}};shops.setAdapter(adapter);}
 void loadStores(){status.setText("Carregando lojas de Timon…");int request=++token;worker.submit(()->{try{
  JSONArray states=new JSONArray(fetch("https://app.mateusmais.com.br/api/products/market/by_states/",null));List<JSONObject> found=new ArrayList<>();List<String> names=new ArrayList<>();
  for(int i=0;i<states.length();i++){JSONObject state=states.getJSONObject(i);if(!state.optString("uf").equals("MA"))continue;JSONArray cities=state.getJSONArray("cities");for(int j=0;j<cities.length();j++){JSONObject city=cities.getJSONObject(j);if(!city.optString("name").equalsIgnoreCase("Timon"))continue;JSONArray m=city.getJSONArray("markets");for(int k=0;k<m.length();k++){JSONObject shop=m.getJSONObject(k);if(shop.optString("name").startsWith("Mix Mateus")){found.add(shop);names.add(shop.getString("name"));}}}}
  runOnUiThread(()->{if(isDestroyed()||token!=request)return;markets=found;spinner(names);String preferred="";try(SQLiteDatabase db=openOrCreateDatabase("regsco.db",MODE_PRIVATE,null);Cursor c=db.rawQuery("SELECT value FROM settings WHERE key='mix_online_store'",null)){if(c.moveToFirst())preferred=c.getString(0);}catch(Exception ignored){}for(int i=0;i<markets.size();i++)if(markets.get(i).optString("id").equals(preferred))shops.setSelection(i);status.setText(found.isEmpty()?"Nenhuma loja de Timon disponibilizada na fonte.":"Confira a loja selecionada.");if(!query.getText().toString().trim().isEmpty()&&!found.isEmpty())search();});
 }catch(Exception e){error(request,"Não foi possível carregar as lojas. Verifique a conexão e tente novamente.");}});}
 void search(){if(!pharmacy&&markets.isEmpty()){loadStores();return;}String rawTerm=query.getText().toString().trim();String term=pharmacy?rawTerm:ProductSearch.alternatives(rawTerm);if(!pharmacy)query.setText(term);if(term.length()>120||!pharmacy&&!ProductSearch.valid(term)){query.setError("Informe um produto, com até 120 caracteres");return;}String source=String.valueOf(shops.getSelectedItem());JSONObject market=pharmacy?null:markets.get(Math.max(0,shops.getSelectedItemPosition()));
  if(market!=null)try(SQLiteDatabase db=openOrCreateDatabase("regsco.db",MODE_PRIVATE,null)){db.execSQL("INSERT OR REPLACE INTO settings(key,value) VALUES('mix_online_store',?)",new Object[]{market.optString("id")});}catch(Exception ignored){}
  int request=++token;results.removeAllViews();status.setText("Consultando "+source+"…");worker.submit(()->{try{List<Offer> list=pharmacy?pharmacy(source,term):mix(market,term,null);
   if(!pharmacy){list.removeIf(o->!ProductSearch.matches(term,o.name));list.sort(java.util.Comparator.comparingLong(o->o.price));}
   runOnUiThread(()->{if(!isDestroyed()&&token==request)render(list,source);});
  }catch(Exception e){error(request,"Consulta indisponível. Não há preço confirmado. Tente novamente; o cadastro local continua disponível.");}});
 }
 void error(int request,String message){runOnUiThread(()->{if(!isDestroyed()&&token==request)status.setText(message);});}
 static String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){throw new IllegalArgumentException(e);}}
 static String fetch(String url,JSONObject body)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(18000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();if(code!=200&&code!=206)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>10000000)throw new IOException("Resposta excessiva");out.write(b,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 static long cents(Object v){try{return new BigDecimal(String.valueOf(v)).movePointRight(2).setScale(0,RoundingMode.HALF_UP).longValueExact();}catch(Exception e){return -1;}}
 static List<Offer> mix(JSONObject store,String query,String category)throws Exception {
  String id=store.getString("id");JSONArray filters=new JSONArray().put(new JSONArray().put("market_id:"+id)).put(new JSONArray().put("for_sale:true"));if(category!=null)filters.put(new JSONArray().put("category:"+category));
  JSONObject body=new JSONObject().put("facets",new JSONArray().put("brand").put("nodes")).put("params","page=0&hitsPerPage=40&facetFilters="+enc(filters.toString())+"&query="+enc(query)).put("index","SHOWCASE_catalog_product_api_index_PROD_sale_price_asc").put("service","meilisearch");
  return parseMix(new JSONObject(fetch("https://app.mateusmais.com.br/api/products/internal/v1/service/",body)),id,store.getString("name"));
 }
 static List<Offer> parseMix(JSONObject data,String id,String name)throws Exception {List<Offer> out=new ArrayList<>();JSONArray hits=data.getJSONArray("hits");for(int i=0;i<hits.length();i++){JSONObject p=hits.getJSONObject(i);long price=cents(p.opt("sale_price"));if(!p.optString("market_id").equals(id)||!p.optBoolean("for_sale")||price<=0||p.optBoolean("is_bulk")||p.optBoolean("is_mva"))continue;Offer o=new Offer();o.name=p.getString("name");o.price=price;o.reference=cents(p.opt("price"));o.source=name;o.image=RemotePhotos.safe(p.optString("small_image",p.optString("image")));o.category=p.optString("category");o.url="https://mateusmais.com.br/produtos/"+enc(id)+"/"+enc(p.getString("objectID"));o.conditional=p.optBoolean("sale_in_multiple")||p.optBoolean("use_wholesale_rule")||(p.optJSONObject("campaignsData")!=null&&p.getJSONObject("campaignsData").length()>0);out.add(o);}return out;}
 static List<Offer> pharmacy(String source,String query)throws Exception {String host=source.equals("Pague Menos")?"www.paguemenos.com.br":"www.drogariaglobo.com.br";JSONArray data=new JSONArray(fetch("https://"+host+"/api/catalog_system/pub/products/search?_from=0&_to=19&O=OrderByBestDiscountDESC"+(query.isEmpty()?"":"&ft="+enc(query)),null));return parsePharmacy(data,source,host,query.isEmpty());}
 static List<Offer> parsePharmacy(JSONArray data,String source,String host,boolean discountOnly)throws Exception{List<Offer> out=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject p=data.getJSONObject(i);String url=p.optString("link");URI uri=new URI(url);if(!"https".equals(uri.getScheme())||!host.equals(uri.getHost()))continue;JSONArray skus=p.optJSONArray("items");if(skus==null)continue;for(int j=0;j<skus.length();j++){JSONObject sku=skus.getJSONObject(j);JSONArray sellers=sku.optJSONArray("sellers");if(sellers==null)continue;for(int k=0;k<sellers.length();k++){JSONObject seller=sellers.getJSONObject(k),value=seller.optJSONObject("commertialOffer");if(value==null||value.optDouble("AvailableQuantity",0)<=0)continue;long price=cents(value.opt("Price")),list=cents(value.opt("ListPrice"));String until=value.optString("PriceValidUntil");if(!until.isEmpty())try{if(java.time.Instant.parse(until).isBefore(java.time.Instant.now()))continue;}catch(Exception e){continue;}if(price<=0||discountOnly&&list<=price)continue;Offer o=new Offer();o.name=sku.optString("nameComplete",p.optString("productName"));o.price=price;o.reference=list;o.source=source+" • "+seller.optString("sellerName",source);o.url=url;o.category="Farmácia";JSONArray images=sku.optJSONArray("images");if(images!=null&&images.length()>0)o.image=RemotePhotos.safe(images.getJSONObject(0).optString("imageUrl"));out.add(o);}}}return out;}
 static BigDecimal[] pack(String name){if(name.toLowerCase(Locale.ROOT).matches(".*(kit|\\d+\\s*[x×]|pack|leve\\s*\\d).*"))return null;java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)(\\d+(?:[.,]\\d+)?)\\s*(kg|ml|g|l)\\b").matcher(name);if(!m.find())return null;BigDecimal size=new BigDecimal(m.group(1).replace(',','.'));String unit=m.group(2).toLowerCase(Locale.ROOT);if(size.signum()<=0||m.find())return null;if(unit.equals("g")||unit.equals("ml"))size=size.divide(BigDecimal.valueOf(1000));return new BigDecimal[]{size,BigDecimal.valueOf(unit.equals("kg")||unit.equals("g")?0:1)};}
 String money(long cents){return NumberFormat.getCurrencyInstance(new Locale("pt","BR")).format(BigDecimal.valueOf(cents,2));}
 void render(List<Offer> offers,String source){status.setText(source+" • "+new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("pt","BR")).format(new Date())+"\n"+(pharmacy?"Preço sem frete; confirme CEP e condições na loja.":"Até 40 resultados do site, filtrados pelo tipo e sabor informados. Compare a embalagem; não garante o menor preço de toda a loja."));if(offers.isEmpty()){text(results,"Nenhuma opção confirmada nesta busca. Confira o nome e o sabor, retire a marca ou tente outra loja. Isso não comprova ausência na loja física.",16);return;}
  Map<String,BigDecimal> best=new HashMap<>();for(Offer o:offers){BigDecimal[] p=pack(o.name);if(pharmacy||o.conditional||p==null)continue;String key=o.category+p[1];BigDecimal n=BigDecimal.valueOf(o.price).divide(p[0],6,RoundingMode.HALF_UP);if(!best.containsKey(key)||n.compareTo(best.get(key))<0)best.put(key,n);}
  for(Offer o:offers){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setBackground(ThemeSkin.card(theme,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,12,0,12);results.addView(card,lp);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);card.addView(head);int px=(int)(96*getResources().getDisplayMetrics().density);ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);photo.setContentDescription("Foto do site: "+o.name);photo.setBackgroundColor(android.graphics.Color.WHITE);head.addView(photo,new LinearLayout.LayoutParams(px,px));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);head.addView(info,new LinearLayout.LayoutParams(0,-2,1));text(info,o.name,17);text(info,money(o.price),22);TextView photoState=text(card,"Carregando foto do site…",11);RemotePhotos.load(this,photo,photoState,o.image);if(o.reference>o.price)text(card,"Referência do site: "+money(o.reference),13);text(card,o.source,13);
   BigDecimal[] p=pack(o.name);if(!pharmacy&&p!=null&&!o.conditional){BigDecimal n=BigDecimal.valueOf(o.price).divide(p[0],6,RoundingMode.HALF_UP);String unit=p[1].signum()==0?"kg":"L";text(card,NumberFormat.getCurrencyInstance(new Locale("pt","BR")).format(n.movePointLeft(2))+" / "+unit,15);if(n.compareTo(best.get(o.category+p[1]))==0)text(card,"Menor valor por "+unit+" nesta busca. Confira marca, tipo, sabor e composição.",13);}
   if(o.conditional)text(card,"Há condições de campanha/quantidade. Confira na loja; não entra na indicação de menor preço.",13);button(card,"Ver produto dentro do app",()->web(o.url));
  }
 }
 static boolean allowed(String url){try{URI u=new URI(url);if(!"https".equals(u.getScheme())||u.getUserInfo()!=null)return false;String host=u.getHost();if(host==null)return false;for(String d:new String[]{"mateusmais.com.br","paguemenos.com.br","drogariaglobo.com.br","drogasil.com.br"})if(host.equals(d)||host.endsWith("."+d))return true;}catch(Exception ignored){}return false;}
 void web(String url){if(!allowed(url))return;WebView view=new WebView(this);WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);android.webkit.CookieManager.getInstance().setAcceptThirdPartyCookies(view,false);view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !allowed(r.getUrl().toString());}@Override public void onReceivedSslError(WebView w,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});AlertDialog d=new AlertDialog.Builder(this).setTitle("Site oficial • confira o CEP").setView(view).setPositiveButton("Voltar",(a,b)->{}).create();d.setOnDismissListener(a->{view.stopLoading();view.destroy();});d.show();d.getWindow().setLayout(-1,-1);view.loadUrl(url);}
 @Override protected void onDestroy(){token++;worker.shutdownNow();super.onDestroy();}
}
